import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as n,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"MiniMax Code 学习地图","description":"MiniMax Code 是最适配 MiniMax 模型的第一方 Coding Agent。本目录只写 Code。Agent / Hailuo / 星野只在家族表占一行。","frontmatter":{"title":"MiniMax Code 学习地图","description":"MiniMax Code 是最适配 MiniMax 模型的第一方 Coding Agent。本目录只写 Code。Agent / Hailuo / 星野只在家族表占一行。","domain":"product","tags":["coding-agent"],"role":"map"},"headers":[],"relativePath":"zh/products/minimax-code/index.md","filePath":"zh/products/minimax-code/index.md","lastUpdated":1787110548000}'),i={name:"zh/products/minimax-code/index.md"};function o(d,t,s,l,m,c){return n(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="minimax-code-学习地图" tabindex="-1">MiniMax Code 学习地图 <a class="header-anchor" href="#minimax-code-学习地图" aria-label="Permalink to &quot;MiniMax Code 学习地图&quot;">​</a></h1><blockquote><p><strong>MiniMax Code</strong> 是 MiniMax 的第一方 Coding Agent。官网原文：「最适配 MiniMax 模型的 Coding Agent」（<a href="https://www.minimaxi.com/" target="_blank" rel="noreferrer">minimaxi.com</a>）。产品文档原文：「MiniMax Code 是一款桌面端 AI Agent 应用。它把对话、项目工作区、文件操作、终端、浏览器、技能、记忆和自动化任务放在同一个本地工作环境里」（<a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">欢迎使用</a>）。</p><p>同一产品还有终端入口 <strong>MiniMax Code CLI</strong>，命令是 <code>mcode</code>（<a href="https://agent.minimaxi.com/docs/cli/quick-start" target="_blank" rel="noreferrer">CLI 快速开始</a>）。它不是另一个产品。</p></blockquote><h2 id="产品家族-retrieve" tabindex="-1">产品家族（Retrieve） <a class="header-anchor" href="#产品家族-retrieve" aria-label="Permalink to &quot;产品家族（Retrieve）&quot;">​</a></h2><p>先对官方一级入口，再决定本站写哪一页。表里每一行都来自 2026-08-19 打开的官网顶栏、About、页脚或文档站，不是搜索摘要。</p><table tabindex="0"><thead><tr><th>官方一级入口</th><th>官方 URL</th><th>本站去向</th></tr></thead><tbody><tr><td><strong>MiniMax Code</strong></td><td><a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">欢迎使用</a>、<a href="https://agent.minimaxi.com/download" target="_blank" rel="noreferrer">下载</a>、<a href="https://agent.minimaxi.com/docs/cli/quick-start" target="_blank" rel="noreferrer">CLI</a></td><td><strong>独立页</strong>（本目录）</td></tr><tr><td>MiniMax Agent</td><td><a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">agent.minimaxi.com</a></td><td>地图一行。网页通用 Agent，正文归 <a href="https://github.com/zenHeart/learn-ai/issues/73" target="_blank" rel="noreferrer">#73</a></td></tr><tr><td>MiniMax Design</td><td><a href="https://design.minimax.io/" target="_blank" rel="noreferrer">design.minimax.io</a></td><td>地图一行。商业内容生产，不是编程 Agent</td></tr><tr><td>MiniMax Hub</td><td>中文 About 一级导航仍用此名（<a href="https://www.minimaxi.com/about" target="_blank" rel="noreferrer">about</a>）</td><td>地图一行。与 Design 撞名，不写第二份教程</td></tr><tr><td>MiniMax Audio / 语音</td><td><a href="https://www.minimax.io/audio" target="_blank" rel="noreferrer">minimax.io/audio</a></td><td>地图一行。语音与音乐</td></tr><tr><td>Hailuo / 海螺 / MiniMax H3</td><td><a href="https://hailuoai.video/" target="_blank" rel="noreferrer">hailuoai.video</a>、<a href="https://platform.minimax.io/docs/guides/models-intro" target="_blank" rel="noreferrer">模型介绍</a></td><td>地图一行。视频生成，不是编程 Agent</td></tr><tr><td>星野</td><td><a href="https://www.xingyeai.com/" target="_blank" rel="noreferrer">xingyeai.com</a></td><td>地图一行。角色互动社区</td></tr><tr><td>Talkie</td><td>国际站 Product 一级（<a href="https://www.minimax.io/" target="_blank" rel="noreferrer">minimax.io</a>）</td><td>地图一行。星野的国际名</td></tr><tr><td>MiniMax M3 等模型</td><td><a href="https://platform.minimax.io/docs/guides/models-intro" target="_blank" rel="noreferrer">models-intro</a></td><td>地图一行。模型不是产品教程</td></tr><tr><td>Token Plan / API</td><td><a href="https://platform.minimaxi.com/" target="_blank" rel="noreferrer">platform.minimaxi.com</a>、<a href="https://platform.minimax.io/" target="_blank" rel="noreferrer">platform.minimax.io</a></td><td>地图一行。开发者平台</td></tr><tr><td>通过 AI 编程工具接入</td><td><a href="https://platform.minimaxi.com/docs/guides/text-ai-coding-tools" target="_blank" rel="noreferrer">text-ai-coding-tools</a></td><td>地图一行。把 M3 接到 Claude Code / Cursor 等，<strong>不是</strong> MiniMax Code</td></tr></tbody></table><p>来源：<a href="https://www.minimaxi.com/" target="_blank" rel="noreferrer">minimaxi.com</a>、<a href="https://www.minimaxi.com/about" target="_blank" rel="noreferrer">minimaxi.com/about</a>、<a href="https://www.minimax.io/" target="_blank" rel="noreferrer">minimax.io</a>、<a href="https://agent.minimaxi.com/docs/llms.txt" target="_blank" rel="noreferrer">agent.minimaxi.com/docs/llms.txt</a>、<a href="https://platform.minimax.io/docs/guides/models-intro" target="_blank" rel="noreferrer">models-intro</a>。</p><p><strong>本目录目标：</strong> 只写 MiniMax Code。同厂其它 AI 产品不在这里展开。</p><p><strong>容易撞名：</strong></p><ul><li><strong>MiniMax Code ≠ MiniMax Agent。</strong> 桌面端在 changelog v3.0.33 正式更名为 MiniMax Code；网页 Agent 仍在 <code>agent.minimaxi.com</code>。文档站品牌仍写「MiniMax Agent 文档」。</li><li><strong><code>mcode</code> ≠ changelog 里的 <code>minimax</code> 快捷方式。</strong> CLI 官方命令是 <code>mcode</code>。</li><li><strong>在 Claude Code 里配 MiniMax-M3 ≠ 安装 MiniMax Code。</strong> 前者是开放平台接入指南。</li><li><strong>Coding / Work 是桌面模式，不是两个产品。</strong></li></ul><p>细节见 <a href="./minimax-code-glossary.html">术语表</a>。</p><h3 id="快速决策-我该用哪个" tabindex="-1">快速决策：我该用哪个？ <a class="header-anchor" href="#快速决策-我该用哪个" aria-label="Permalink to &quot;快速决策：我该用哪个？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做什么？</span></span>
<span class="line"><span>├── 对着本地仓库写代码 / 改 bug / 看 diff / 跑命令</span></span>
<span class="line"><span>│   └── → MiniMax Code</span></span>
<span class="line"><span>│       ├── 要图形界面、浏览器预览、定时任务、手机遥控？</span></span>
<span class="line"><span>│       │     → 桌面端（下载页）</span></span>
<span class="line"><span>│       ├── 要终端 TUI / 脚本 / CI / 编辑器 ACP？</span></span>
<span class="line"><span>│       │     → CLI（命令 mcode）</span></span>
<span class="line"><span>│       └── 任务要拆给多个专家 Agent？</span></span>
<span class="line"><span>│             → 同一产品里的 Agent Team</span></span>
<span class="line"><span>├── 在浏览器里做通用长任务，不一定绑本地仓库</span></span>
<span class="line"><span>│   └── → MiniMax Agent（#73，本目录不写）</span></span>
<span class="line"><span>├── 只要把 MiniMax-M3 接到已经在用的 Claude Code / Cursor</span></span>
<span class="line"><span>│   └── → 开放平台「通过 AI 编程工具接入」，不是本产品</span></span>
<span class="line"><span>├── 生视频 / 改视频</span></span>
<span class="line"><span>│   └── → Hailuo / MiniMax H3 / MiniMax Design</span></span>
<span class="line"><span>├── 语音 / 音乐</span></span>
<span class="line"><span>│   └── → MiniMax Audio</span></span>
<span class="line"><span>└── 角色扮演 / 陪伴</span></span>
<span class="line"><span>    └── → 星野（国内）或 Talkie（国际）</span></span></code></pre></div><h2 id="minimax-code-的两张使用面" tabindex="-1">MiniMax Code 的两张使用面 <a class="header-anchor" href="#minimax-code-的两张使用面" aria-label="Permalink to &quot;MiniMax Code 的两张使用面&quot;">​</a></h2><p>官方 CLI 文档原文：「客户端适合图形化任务管理和结果查看，CLI 更贴近代码仓库、终端、脚本、CI 与编辑器。」（<a href="https://agent.minimaxi.com/docs/cli/features" target="_blank" rel="noreferrer">功能介绍</a>）</p><table tabindex="0"><thead><tr><th>使用面</th><th>入口</th><th>用在哪</th></tr></thead><tbody><tr><td>桌面端</td><td><a href="https://agent.minimaxi.com/download" target="_blank" rel="noreferrer">国内下载</a> / <a href="https://agent.minimax.io/download" target="_blank" rel="noreferrer">海外下载</a></td><td>任务、工作区、浏览器、定时任务、Remote Control</td></tr><tr><td>CLI · TUI</td><td><code>mcode</code></td><td>终端里对着仓库持续对话</td></tr><tr><td>CLI · Headless</td><td><code>mcode exec</code></td><td>脚本、CI</td></tr><tr><td>CLI · ACP</td><td><code>mcode acp</code></td><td>被 Zed 等 ACP 宿主嵌入</td></tr></tbody></table><p>桌面端另有 Coding / Work 两种<strong>模式</strong>（同一套 Agent 能力，界面暴露不同）。见 <a href="./minimax-code.html">教程</a>。</p><h2 id="什么时候值得试" tabindex="-1">什么时候值得试 <a class="header-anchor" href="#什么时候值得试" aria-label="Permalink to &quot;什么时候值得试&quot;">​</a></h2><p><strong>值得试</strong></p><ul><li>你要第一方 Agent，而不是只在别的工具里换一个 MiniMax 模型。</li><li>你需要桌面端把仓库、终端、浏览器、技能、记忆放在同一工作区。</li><li>你需要终端里的 <code>mcode</code>：TUI、<code>exec</code>、ACP。</li><li>你已经有 MiniMax 账号或 Token Plan。M3 博文原文：「MiniMax Code can be used with MiniMax Token Plans。」</li></ul><p><strong>先别急</strong></p><ul><li>你只要在已有 Claude Code / Cursor 里调用 M3 —— 走 <a href="https://platform.minimaxi.com/docs/guides/text-ai-coding-tools" target="_blank" rel="noreferrer">开放平台接入</a>，不要装本产品。</li><li>你要的是网页通用 Agent —— 那是 MiniMax Agent（#73）。</li><li>你要生视频或角色陪伴 —— Hailuo / 星野，不是 Code。</li><li>你需要 Linux 桌面客户端 —— 官方桌面文档只写 macOS 和 Windows。CLI 支持 macOS、Windows、常见 Linux 和 WSL，暂不支持 Alpine / musl。</li></ul><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>读什么</th><th>目标</th></tr></thead><tbody><tr><td>1. 装上能跑</td><td><a href="./minimax-code.html">教程</a> 的桌面或 CLI 安装</td><td>登录后发出第一条任务</td></tr><tr><td>2. 会选模式和工作区</td><td><a href="./minimax-code.html">教程</a> 的 Coding / Work、工作区、权限</td><td>敢让它改本地代码</td></tr><tr><td>3. 接进工作流</td><td><a href="./minimax-code-cookbook.html">Cookbook</a></td><td>Agent Team、<code>mcode exec</code>、ACP</td></tr><tr><td>4. 回查参数</td><td><a href="./minimax-code-cheatsheet.html">速查表</a></td><td>命令、slash、权限档、官方链接</td></tr><tr><td>5. 理清名字</td><td><a href="./minimax-code-glossary.html">术语表</a></td><td>Code vs Agent、桌面 vs CLI、模式正交</td></tr></tbody></table><h2 id="功能速查" tabindex="-1">功能速查 <a class="header-anchor" href="#功能速查" aria-label="Permalink to &quot;功能速查&quot;">​</a></h2><p>下表只列官方文档页里出现的能力。</p><table tabindex="0"><thead><tr><th>能力</th><th>一句话</th><th>官方文档</th></tr></thead><tbody><tr><td>Coding / Work</td><td>同一套 Agent，开发工具暴露程度不同</td><td><a href="https://agent.minimaxi.com/docs/code/workflows/modes" target="_blank" rel="noreferrer">modes</a></td></tr><tr><td>工作区</td><td>选本地项目目录，再读文件、跑命令</td><td><a href="https://agent.minimaxi.com/docs/code/workflows/workspace" target="_blank" rel="noreferrer">workspace</a></td></tr><tr><td>权限确认</td><td>改文件、跑命令、外部工具前先问你</td><td><a href="https://agent.minimaxi.com/docs/code/workflows/permissions" target="_blank" rel="noreferrer">permissions</a></td></tr><tr><td>Agent Team</td><td>按复杂度拆给多个专家 Agent</td><td><a href="https://agent.minimaxi.com/docs/code/agents/team" target="_blank" rel="noreferrer">team</a></td></tr><tr><td>技能 / 记忆 / 自定义 Agent</td><td>复用流程，沉淀偏好</td><td><a href="https://agent.minimaxi.com/docs/llms.txt" target="_blank" rel="noreferrer">llms.txt 桌面树</a></td></tr><tr><td>定时任务 / Remote Control / IM</td><td>计划执行、手机遥控、微信飞书 Telegram</td><td>桌面 <code>/docs/code/automation/*</code></td></tr><tr><td>CLI TUI / exec / acp</td><td>终端、脚本、编辑器</td><td><a href="https://agent.minimaxi.com/docs/cli/features" target="_blank" rel="noreferrer">features</a></td></tr><tr><td>Token Plan 与签到积分</td><td>产品内查看；签到数字见用量页</td><td><a href="https://agent.minimaxi.com/docs/code/account/usage" target="_blank" rel="noreferrer">usage</a></td></tr></tbody></table><p>模型机制（MSA、训练、benchmark）不在本目录展开，见 <a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a> 和 <a href="https://www.minimax.io/blog/minimax-m3" target="_blank" rel="noreferrer">M3 博文</a>。</p>`,27)])])}const M=a(i,[["render",o]]);export{f as __pageData,M as default};
